# Review package: 019fed8bb4dd668d5f561fa8cb88829c445ae84b..4ecae16

## Commits
4ecae16 Add basic greeting function with custom formatting
b698500 Add greeting implementation plan

## Files changed
 greet.js      | 16 ++++++++++++++++
 greet.test.js | 38 ++++++++++++++++++++++++++++++++++++++
 plan.md       | 24 ++++++++++++++++++++++++
 3 files changed, 78 insertions(+)

## Diff
diff --git a/greet.js b/greet.js
new file mode 100644
index 0000000..14bb911
--- /dev/null
+++ b/greet.js
@@ -0,0 +1,16 @@
+function greet(name, format) {
+  // Handle empty, null, or undefined names gracefully
+  const effectiveName = name || 'friend';
+
+  // Apply custom formatting based on the format parameter
+  switch (format) {
+    case 'formal':
+      return `Good day, ${effectiveName}.`;
+    case 'casual':
+      return `Hey, ${effectiveName}!`;
+    default:
+      return `Hello, ${effectiveName}!`;
+  }
+}
+
+module.exports = { greet };
diff --git a/greet.test.js b/greet.test.js
new file mode 100644
index 0000000..913eee1
--- /dev/null
+++ b/greet.test.js
@@ -0,0 +1,38 @@
+const { test } = require('node:test');
+const assert = require('node:assert');
+const { greet } = require('./greet');
+
+test('greet returns formatted greeting with name', () => {
+  const result = greet('Alice');
+  assert.strictEqual(result, 'Hello, Alice!');
+});
+
+test('greet with formal format', () => {
+  const result = greet('Bob', 'formal');
+  assert.strictEqual(result, 'Good day, Bob.');
+});
+
+test('greet with casual format', () => {
+  const result = greet('Charlie', 'casual');
+  assert.strictEqual(result, 'Hey, Charlie!');
+});
+
+test('greet handles empty string gracefully', () => {
+  const result = greet('');
+  assert.strictEqual(result, 'Hello, friend!');
+});
+
+test('greet handles undefined gracefully', () => {
+  const result = greet();
+  assert.strictEqual(result, 'Hello, friend!');
+});
+
+test('greet handles null gracefully', () => {
+  const result = greet(null);
+  assert.strictEqual(result, 'Hello, friend!');
+});
+
+test('greet with unknown format falls back to default', () => {
+  const result = greet('Dave', 'unknown');
+  assert.strictEqual(result, 'Hello, Dave!');
+});
diff --git a/plan.md b/plan.md
new file mode 100644
index 0000000..3770877
--- /dev/null
+++ b/plan.md
@@ -0,0 +1,24 @@
+# Single-Task Greeting Plan
+
+**Spec:** Add a small greeting customization feature.
+
+**Goal:** The app can greet a provided name with custom formatting.
+
+---
+
+### Task 1: Add basic greeting function
+
+**Files:**
+- Create: `greet.js`
+- Create: `greet.test.js`
+
+**Acceptance Criteria:**
+- greet(name) returns a formatted greeting string.
+- The default behavior handles empty input gracefully.
+- Tests cover both normal and edge cases.
+
+- [ ] **Step 1: Implement greet function in greet.js**
+- [ ] **Step 2: Add tests for greet in greet.test.js**
+- [ ] **Step 3: Run tests to verify**
+
+---

